  ('cb0c2d43-c427-5258-aa94-c793c30e623f', null, (select id from public.skills where slug = 'read-g12-connections'), null, 'medium',
   $q$How does the author connect the success of Halvik's dye works to the growth of the technical college?$q$, $q$[{"text":"The college grew so that it could study the waste the dye works poured into the river.","is_correct":false,"misconception_token":"confuses-sequence"},{"text":"The college trained Halvik, and his success persuaded it to expand its chemistry classes.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Halvik and Ebeling paid the college to double its classes so they could hire its students.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"The success drew rival dye makers, whose competition created demand for trained chemists.","is_correct":true}]$q$::jsonb, $q$The success drew rival dye makers, whose competition created demand for trained chemists.$q$, $q$Paragraph 3 traces a chain: success drew imitators, competition led factories to hire trained chemists, and the college doubled its classes "to supply them." The passage never says the college trained Halvik or that he paid for its growth.$q$, 'draft', 'a2cbc400-e47b-5386-892a-8feb50abfc3f')
